# NAAC / NBA evidence computed from CampusSphere's records. Every metric says where its numbers
# come from and how far to trust them:
#   live       real records the college generated by using CampusSphere
#   simulated  generated data standing in until real records exist (e.g. session headcounts)
#   test_mode  the process runs online but in test mode (payments)
#   missing    CampusSphere doesn't capture this yet: listed as an evidence gap with how to close it
# Criterion mappings follow the NAAC revised accreditation framework (key indicators) and the NBA
# SAR criteria for UG engineering programmes; the IQAC should confirm metric numbers against the
# manual it files under.
import re
from collections import Counter, defaultdict
from datetime import datetime
from statistics import mean
from typing import Optional

from sqlalchemy.orm import Session

from backend.app.accreditation.desks import _hours, desk_wall, fmt_hours, percentile
from backend.app.accreditation.scope import PILOT_BUILDING, Scope, dept_key
