STAKEHOLDERS = {"curriculum": "students", "faculty": "teachers", "employer": "employers", "alumni": "alumni"}


def feedback(c: Ctx) -> dict:
    """NAAC 1.4.1 (stakeholders giving feedback on the syllabus) and 1.4.2 (collected, analysed, acted upon, published);
    NBA 7 / 9.2 / 9.3. Per completed year, for the scope's programmes and college-wide forms."""
    from backend.app.models.feedback import FeedbackATRModel, FeedbackFormModel, FeedbackResponseModel
    current = academic_year(c.now)
    forms = [f for f in c.db.query(FeedbackFormModel).all() if f.programme is None or c.scope.has(f.programme)]
    if not forms:
        return gap("Structured feedback and action taken", "No feedback forms are recorded for this scope.",
                   "Create feedback forms (students, teachers, alumni, employers) under Feedback, then write and publish the ATRs.")(c)
    counts = {}
    for fid, in c.db.query(FeedbackResponseModel.form_id).filter(FeedbackResponseModel.form_id.in_([f.id for f in forms])):
        counts[fid] = counts.get(fid, 0) + 1
    atrs = {a.form_id: a for a in c.db.query(FeedbackATRModel).filter(FeedbackATRModel.form_id.in_([f.id for f in forms]))}
    rows, latest = [], None
    for y in sorted({f.year for f in forms if f.year < current}):
        fy = [f for f in forms if f.year == y and counts.get(f.id)]
        groups = sorted({STAKEHOLDERS[f.kind] for f in fy if f.kind in STAKEHOLDERS})
        approved = [f for f in fy if f.id in atrs and atrs[f.id].status == "approved"]
        published = [f for f in approved if atrs[f.id].published]
        stage = ("A · collected, analysed, acted upon and published" if published and len(published) == len([f for f in approved if f.kind != "teaching"])
                 else "B · collected, analysed and acted upon" if approved else "C · collected and analysed" if fy else "E")
        option_141 = "ABCDE"[4 - min(4, len(groups))]
        rows.append([y, len(fy), sum(counts.get(f.id, 0) for f in fy), ", ".join(groups) or "—", f"{option_141} ({len(groups)} of 4)", stage])
        latest = rows[-1]
    sss = [f for f in forms if f.kind == "sss" and counts.get(f.id)]
    return {
        "title": "Structured feedback and action taken",
        "value": f"1.4.1 option {latest[4][0]} · 1.4.2 option {latest[5][0]} ({latest[0]})" if latest else "No completed year yet",
        "detail": (f"{latest[0]}: {latest[1]} forms, {latest[2]:,} responses from {latest[3]}; {latest[5][4:]}. " if latest else "") +
                  (f"Student Satisfaction Survey dry run: {counts[sss[-1].id]} responses ({sss[-1].year}). " if sss else "") +
                  "Answers are anonymous; teachers' own feedback stays internal.",
        "status": "live",
        "source": _src("feedback_forms + feedback_responses + feedback_atr", sum(counts.values())),
        "table": _table(["Year", "Forms", "Responses", "Stakeholders on the syllabus", "1.4.1", "1.4.2"], rows),
    }


def results(c: Ctx) -> dict:
    """NAAC 2.5.1 (days to declare results), 2.5.2 (evaluation grievances), 2.6.3 (pass percentage);
    NBA 4.1-4.4 (enrolment ratio, success index, academic performance index)."""
    from backend.app.api.v1.endpoints.results import overview
    from backend.app.models.feedback import ResultSummaryModel
    progs = sorted({dept_key(p) for (p,) in c.db.query(ResultSummaryModel.programme).distinct() if c.scope.has(p)})
    if not progs:
        return gap("Examination results", "No semester results or batch outcomes are recorded for this scope.",
                   "The Exam Cell enters each semester's results and each batch's figures under Results.")(c)
    rows, lines = [], []
    for p in progs:
        o = overview(c.db, p)
        for y in o["years"][-5:]:
            rows.append([p, y["year"], y["appeared"], f"{y['pass_pct']}%", y["days_to_declare"], f"{y['complaints_pct']}%"])
        done = [b for b in o["batches"] if b["success_total"] is not None][-3:]
        if o["years"]:
            last = o["years"][-1]
            lines.append(f"{p} {last['year']}: {last['pass_pct']}% passed; results declared in {last['days_to_declare']} days on average")
        if done:
            lines.append(f"{p} success index (last {len(done)} graduated batches): {sum(b['success_clean'] for b in done) / len(done):.2f} "
                         f"without backlogs, {sum(b['success_total'] for b in done) / len(done):.2f} in all")
    last = rows[-1] if rows else None
    missing = sorted(d for d in c.scope.departments if d not in progs)
    return {
        "title": "Examination results",
        "value": f"{last[3]} pass · {last[4]} days to declare ({last[1]})" if last else "No results yet",
        "detail": ". ".join(lines) + "." + (f" Not recorded for {', '.join('Civil' if m == 'CIVIL' else m for m in missing)} yet." if missing else ""),
        "status": "live",
        "source": _src("result_summaries + batch_outcomes (Exam Cell totals)", len(rows)),
        "table": _table(["Programme", "Year", "Appeared", "Pass %", "Days to declare", "Grievances"], rows),
    }


def outcomes(c: Ctx) -> dict:
    """NBA 3.1-3.3, 7.1 / NAAC 2.6.1-2.6.2: COs, CO-PO mapping and attainment of the latest completed year."""
    from backend.app.models.obe import ObeActionModel, ObeCourseModel
    from backend.app.obe.attainment import programme_attainment
    current = academic_year(c.now)
    progs = sorted({dept_key(p) for (p,) in c.db.query(ObeCourseModel.programme).distinct() if c.scope.has(p)})
    if not progs:
        return gap("Course and programme outcome attainment", "No COs, CO-PO mapping or assessments are recorded for this scope.",
                   "Record each course's COs and mapping and import its marks sheets under Outcomes (OBE).")(c)
    rows, met, measured, lines = [], 0, 0, []
    for p in progs:
        years = sorted({y for (y,) in c.db.query(ObeCourseModel.year).filter(ObeCourseModel.programme == p).distinct() if y < current})
        for y in years[-3:]:
            r = programme_attainment(c.db, p, y)
            vals = [o for o in r["outcomes"] if o["attainment"] is not None]
            rows.append([p, y, len(r["courses"]), len(vals), sum(o["met"] for o in vals),
                         ", ".join(f"{g['code']} {g['attainment']:.2f}" for g in r["gaps"]) or "none"])
            if y == years[-1]:
                met += sum(o["met"] for o in vals)
                measured += len(vals)
                lines.append(f"{p} {y}: {sum(o['met'] for o in vals)} of {len(vals)} POs / PSOs at or above target {r['settings']['po_target']}")
    actions = c.db.query(ObeActionModel).filter(ObeActionModel.programme.in_(progs)).all()
    missing = sorted(d for d in c.scope.departments if d not in progs)
    return {
        "title": "Course and programme outcome attainment",
        "value": f"{met} of {measured} POs / PSOs met" if measured else "No completed year yet",
        "detail": "; ".join(lines) + f". {len(actions)} actions recorded on gaps ({sum(a.status == 'done' for a in actions)} done)." +
                  (f" Not recorded for {', '.join('Civil' if m == 'CIVIL' else m for m in missing)} yet." if missing else ""),
        "status": "live",
        "source": _src("obe_courses + obe_questions (per-question totals)", len(rows)),
        "table": _table(["Programme", "Year", "Courses", "POs / PSOs measured", "Met target", "Below target"], rows),
    }


def placement(c: Ctx) -> dict:
    """NAAC 5.2.1-5.2.2 / NBA 4.6: share of each outgoing batch placed, in higher studies or starting up; the
    batch passing out now counts from the Placement Cell's drives so far."""
    from backend.app.api.v1.endpoints.placements import batch_report
    from backend.app.models.placements import PlacementBatchSummaryModel, PlacementDriveModel
    hist = [h for h in c.db.query(PlacementBatchSummaryModel).all() if c.scope.has(h.department)]
    depts = sorted({dept_key(h.department) for h in hist} |
                   {dept_key(d) for dr in c.db.query(PlacementDriveModel).all() for d in (dr.departments or []) if c.scope.has(d)})
    if not depts:
        return gap("Placements and higher studies", "No placement drives or outgoing-batch numbers are recorded for this scope.",
                   "Record drives and results in the Placement Cell; enter earlier batches' final numbers.")(c)
    rows, last3 = [], []
    for h in sorted(hist, key=lambda h: (h.department, h.batch)):
        progressed = h.placed + h.higher_studies + h.entrepreneurs
        rows.append([dept_key(h.department), h.batch, h.eligible, h.placed, h.higher_studies, h.entrepreneurs,
                     f"{100 * h.placed / h.eligible:.0f}%", f"{h.median_ctc:g} LPA" if h.median_ctc else "—"])
    latest = max((h.batch for h in hist), default=None)
    for d in depts:
        mine = sorted((h for h in hist if dept_key(h.department) == d), key=lambda h: h.batch)[-3:]
        last3 += mine
    now_rows = []
    for d in depts:
        current = sorted({dr.batch for dr in c.db.query(PlacementDriveModel).all() if d in (dr.departments or []) and dr.kind == "job"})
        for b in current:
            if latest and b <= latest:
                continue
            r = batch_report(c.db, d, b)
            if r["students"]:
                now_rows.append([d, f"{b} (so far)", r["students"], r["placed"], "—", "—", f"{r['placed_pct']:.0f}%",
                                 f"{r['median_ctc']:g} LPA" if r["median_ctc"] else "—"])
    eligible = sum(h.eligible for h in last3)
    placed = sum(h.placed for h in last3)
    progressed = sum(h.placed + h.higher_studies + h.entrepreneurs for h in last3)
    lat = [h for h in hist if h.batch == latest]
    lat_pct = 100 * sum(h.placed for h in lat) / sum(h.eligible for h in lat) if lat else None
    missing = sorted(d for d in c.scope.departments if d not in depts)
    return {
        "title": "Placements and higher studies",
        "value": (f"{lat_pct:.0f}% of the {latest} batch placed" if lat_pct is not None else
                  f"{now_rows[0][6]} of the {now_rows[0][1]} batch placed" if now_rows else "No outgoing batch yet"),
        "detail": (f"Last three outgoing batches: {100 * placed / eligible:.0f}% placed, {100 * progressed / eligible:.0f}% placed, "
                   f"in higher studies or self-employed. " if eligible else "") +
                  (f"The current final year so far: {now_rows[0][3]} of {now_rows[0][2]} placed. " if now_rows else "") +
                  (f"No placement records for {', '.join('Civil' if m == 'CIVIL' else m for m in missing)} yet." if missing else ""),
        "status": "live",
        "source": _src("placement_batch_summaries + placement_registrations", len(hist) + len(now_rows)),
        "table": _table(["Branch", "Batch", "Eligible", "Placed", "Higher studies", "Entrepreneurs", "Placed %", "Median"],
                        rows + now_rows),
    }


# ── Criterion: governance ───────────────────────────────────────────────────────
def e_governance(c: Ctx) -> dict:
    db = c.db
    dept_of = dict(db.query(UserModel.id, UserModel.department).all())
    payments = [p for p in db.query(PaymentModel).filter(PaymentModel.status == "paid").all() if c.scope.has(dept_of.get(p.user_id))]
    real_payments = [p for p in payments if p.provider != "test"]
    exam_docs = [r for r in c.requests if DOC_TYPES.get(r.doc_type, {}).get("counter_name") == "Exam Cell"]
    approvals = sum(1 for r in c.requests for s in (r.steps or []) if s.get("acted_at"))
    exit_ids = {e.id for e in c.exits}
    clearances = sum(1 for i in db.query(ClearanceItemModel).all() if i.exit_id in exit_ids)
    adm = len(c.admissions)
    areas = [
        ["Administration", "Certificate requests, multi-level approvals, QR-verified documents", f"{approvals} approvals", "live" if approvals else "missing"],
        ["Student admission and support", "Joining checklist, document verification, enrolment", f"{adm} applications", "live" if adm else "missing"],
        ["Finance and accounts", "Online fees, dues and receipts",
         f"{len(payments)} payments", "live" if real_payments else ("test_mode" if payments else "missing")],
        ["Examination", "Provisional certificates, CMM, transcripts via the Exam Cell", f"{len(exam_docs)} requests", "live" if exam_docs else "missing"],
        ["Student exit", "No-dues clearance across seven units", f"{clearances} sign-offs", "live" if clearances else "missing"],
        ["Academic planning", "Timetable, clash report, substitutions", f"{len(c.entries)} timetable rows", "live" if c.entries else "missing"],
    ]
    covered = [a for a in areas if a[3] != "missing"]
    statuses = {a[3] for a in covered}
    return {
        "title": "E-governance: areas of operation run online",
        "value": f"{len(covered)} of {len(areas)} areas",
        "detail": "Payments run in test mode until a live gateway is connected." if "test_mode" in statuses else
                  "Each area keeps its records and audit trail in CampusSphere.",
        "status": "test_mode" if "test_mode" in statuses else ("live" if covered else "missing"),
        "source": "document_requests, admissions, payments, clearance_items, timetable_entries",
        "table": _table(["Area", "What runs online", "Records", "Status"], areas),
    }


def audit_trail(c: Ctx) -> dict:
    db = c.db
    approvals = sum(1 for r in c.requests for s in (r.steps or []) if s.get("acted_at"))
    verifiable = sum(1 for r in c.requests if r.status == "approved")
    tt = db.query(TimetableAuditLogModel).count()
    sub_ids = {s.id for s in db.query(SubstitutionModel).all() if s.section in c.sections}
    sub = sum(1 for a in db.query(SubstitutionAuditLogModel).all() if a.substitution_id in sub_ids)
    rows = [["Approval decisions (who, when, remarks)", approvals], ["QR-verifiable documents issued", verifiable],
            ["Timetable changes logged (whole Civil & IT timetable)", tt], ["Substitution changes logged", sub]]
    return {
        "title": "Audit trail and document authenticity",
        "value": f"{approvals + tt + sub:,} logged actions",
        "detail": f"{verifiable} issued documents can be checked by anyone at /verify.",
        "status": "live" if approvals or tt or sub else "missing",
        "source": "document_requests.steps, timetable_audit_logs, substitution_audit_logs",
        "table": _table(["Record", "Count"], rows),
    }


def service_turnaround(c: Ctx) -> dict:
    w = c.wall
    s = w["summary"]
    return {
        "title": f"Service turnaround against the {STEP_SLA_HOURS}-hour desk target",
        "value": f"{s['within_sla_pct']}% of steps on time" if s["within_sla_pct"] is not None else "No completed steps",
        "detail": (f"Median {fmt_hours(s['median_hours'])} per desk; {s['pending']} waiting now, {s['overdue']} overdue. "
                   if s["median_hours"] is not None else "") + "Live on the desk turnaround wall.",
        "status": "live" if s["handled"] or s["pending"] else "missing",
        "source": "document_requests.steps (acted_at)",
        "table": _table(["Stage", "Handled", "Median time", "On time", "Waiting"],
                        [[st["label"], st["handled"], fmt_hours(st["median_hours"]),
                          f"{st['within_sla_pct']}%" if st["within_sla_pct"] is not None else "—", st["pending"]]
                         for st in w["stages"]]),
    }


