STATUS_ORDER = ["live", "test_mode", "simulated", "missing"]


def _coverage(metrics: list) -> dict:
    counts = Counter(m["status"] for m in metrics)
    total = len(metrics) or 1
    return {"total": len(metrics), **{s: counts.get(s, 0) for s in STATUS_ORDER},
            "percent": round(100 * counts.get("live", 0) / total)}


class ScopeError(ValueError):
    """The framework can't be reported for this scope (NBA needs one programme)."""


def build_report(db: Session, framework: str = "naac", scope_id: str = "both") -> dict:
    """NAAC can cover the whole pilot or one programme; NBA accredits programmes, so it needs one."""
    if framework == "nba" and scope_id == "both":
        raise ScopeError("NBA accredits each programme separately: choose Civil or IT.")
    fw = FRAMEWORKS[framework]
    scope = Scope(scope_id)
    ctx = Ctx(db, scope)
    grouped = defaultdict(list)
    for mid, naac, nba, fn in METRICS:
        mapping = naac if framework == "naac" else nba
        if mapping is None:
            continue
        crit, indicator = mapping
        try:
            m = fn(ctx)
        except Exception as e:   # one broken metric shouldn't take the whole report down
            m = {"title": mid, "value": "Couldn't compute", "detail": str(e), "status": "missing", "source": None}
        grouped[crit].append({"id": mid, "indicator": indicator, **m})

    criteria = [{"code": code, "title": title, "metrics": grouped.get(code, []),
                 "coverage": _coverage(grouped.get(code, []))} for code, title in fw["criteria"]]
    every = [m for c in criteria for m in c["metrics"]]
    gaps = [{"criterion": c["code"], "criterion_title": c["title"], "indicator": m["indicator"], "title": m["title"],
             "why": m.get("detail"), "fix": m.get("fix")}
            for c in criteria for m in c["metrics"] if m["status"] in ("missing", "simulated")]
    return {
        "framework": {"id": fw["id"], "name": fw["name"], "long_name": fw["long_name"]},
        "scope": scope.describe(),
        "generated_at": ctx.now.isoformat(),
        "academic_year": academic_year(ctx.now),
        "coverage": _coverage(every),
        "criteria": criteria,
        "gaps": gaps,
        "note": f"Covers the {scope.meta['label']}"
                + ("" if scope.id == "both" else " (part of the Civil & IT Block pilot)")
                + ": only Civil and IT timetables, faculty and rooms are loaded so far. Mappings follow the NAAC "
                  "revised accreditation framework and NBA SAR criteria; confirm metric numbers against the manual "
                  "your IQAC files under before submission.",
    }
